pair P=(7,0), Q=(14,0), R=P+7expi(pi/3), M=(10,1.2);
draw(M--P--Q--R--M--Q);
draw(P--R);

label("$P$",P,W);
label("$Q$",Q,E);
label("$R$",R,W);
label("$M$",M,NE);
