B[1] = extension(C[0],A[0],P,reflect(P + R,P - R)*(B[0]));
C[1] = extension(A[0],B[0],P,reflect(P + R,P - R)*(C[0]));

draw((P - R)--(P + R),red);
draw(A[1]--B[1]--C[1]--cycle,blue);
draw(A[0]--B[0]--C[0]--cycle);
draw(A[0]--P);
draw(B[0]--P);
draw(C[0]--P);
draw(P--A[1]);
draw(P--B[1]);
draw(P--C[1]);
draw(A[1]--B[0]);
draw(A[1]--B[0]);

label("$A$", A[0], N);
label("$B$", B[0], S);
label("$C$", C[0], SE);
dot("$A'$", A[1], SW);
